const context = $('Nexus Runtime Context').first().json || {};
const setup = context.setup || {};
const requestText = String(setup.request_text || '').trim();
const sheetUrl = String(setup.sheet_csv_url || '').trim();
const source = $input.first()?.json;
const rawSheet = typeof source === 'string'
  ? source
  : typeof source?.data === 'string'
    ? source.data
    : JSON.stringify(source || {}, null, 2);
const escapeHtml = (value) => String(value || '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('\"', '&quot;')
  .replaceAll("'", '&#039;');
const preview = rawSheet.slice(0, 5000);
return [{
  json: {
    title: 'Regular product test output',
    summary: `Processed the request and read ${rawSheet.length} characters from the test sheet.`,
    content_html: `<section style="font-family:Arial,sans-serif;color:#172033;line-height:1.6"><h1 style="margin:0 0 12px">Regular Nexus product test passed</h1><p><strong>Customer request:</strong> ${escapeHtml(requestText)}</p><p><strong>Sheet source:</strong> <a href="${escapeHtml(sheetUrl)}" target="_blank" rel="noopener noreferrer">Open test sheet</a></p><h2 style="margin:22px 0 8px">Sheet response preview</h2><pre style="white-space:pre-wrap;background:#f4f6fa;padding:16px;border-radius:10px;border:1px solid #dce2eb">${escapeHtml(preview)}</pre></section>`,
    output_type: 'report'
  }
}];
